"use client";
import { ArtemisScope } from "./artemis-scope";
import View0 from "./components/settings-pages/variants/01-profile";
import View1 from "./components/settings-pages/variants/02-workspace";
const variants = {"profile":View0,"workspace":View1};
export interface ArtemisSettingsProps { className?: string; variant?: "profile" | "workspace"; }
export function ArtemisSettings({ className, variant = "profile" }: ArtemisSettingsProps) {const View = variants[variant];return <ArtemisScope className={className}><div className="art:flex art:w-full art:min-w-0 art:flex-col art:items-center"><View/></div></ArtemisScope>;}

"use client";
// @zeus-internal
import { useId as useArtemisInstanceId } from "react";
import { useState, useEffect } from "react";
import { motion, AnimatePresence, MotionConfig, useReducedMotion } from "motion/react";
import { Dialog, DialogBackdrop, DialogPanel, DialogTitle } from "../../../lib/headless";
import { Check, Copy, X } from "lucide-react";
import { ARTEMIS_EASE_OUT, ARTEMIS_SPRING_PANEL } from "../../../lib/ease";
import { ContentSelect } from "./01-profile/content-select";
import { PressButton, FieldBox, Toggle } from "./01-profile/controls";
export default function SettingsPagesProfile() {
const artemisInstanceId = useArtemisInstanceId();


    const reduce = useReducedMotion();
    const initial = { name: "Workspace Studio", semantic: true, insights: true, subdomain: "workspace-studio", domain: "", content: "Workspace overview", logo: null as string | null };
    const [saved, setSaved] = useState(initial);
    const [draft, setDraft] = useState(initial);
    const dirty = JSON.stringify(saved) !== JSON.stringify(draft);
    const [menuOpen, setMenuOpen] = useState(false);
    const [active, setActive] = useState("profile");
    const [saving, setSaving] = useState(false);
    const [error, setError] = useState("");
    const [logoError, setLogoError] = useState("");
    const [status, setStatus] = useState("");
    const [copy, setCopy] = useState("");
    useEffect(() => {
        if (!copy)
            return;
        const timer = setTimeout(() => setCopy(""), 2500);
        return () => clearTimeout(timer);
    }, [copy]);
    const [editing, setEditing] = useState("");
    const toggleEdit = (key: string) => setEditing(current => current === key ? "" : key);
    const update = <K extends keyof typeof initial>(key: K, value: typeof initial[K]) => { setDraft(d => ({ ...d, [key]: value })); setStatus(""); };
    const message = saving ? "Saving changes\u2026" : dirty ? "You have unsaved changes." : status || "You\u2019re all up to date.";
    async function copyId() {
        try {
            await navigator.clipboard.writeText("org_workspace_01");
            setCopy("copied");
        }
        catch {
            setCopy("error");
        }
    }
    function uploadLogo(file: File | undefined) {
        if (!file)
            return;
        if (!["image/png", "image/jpeg", "image/webp"].includes(file.type) || file.size > 2 * 1024 * 1024) {
            setLogoError("Choose a PNG, JPG, or WebP image under 2 MB.");
            return;
        }
        setLogoError("");
        const reader = new FileReader();
        reader.onload = () => { if (typeof reader.result === "string")
            update("logo", reader.result); };
        reader.readAsDataURL(file);
    }
    const navigation = (<nav aria-label="Organization settings" className="art:space-y-7">
              <div>
                <p className="art:mb-2 art:px-3 art:text-xs art:font-medium art:uppercase art:tracking-wide art:text-muted-foreground">
                  {"Organization"}
                </p>
                <div className="art:space-y-1">
                  <a href={`#${artemisInstanceId}-R_9bsnpfdb_-profile`} aria-current={active === "profile" ? "location" : undefined} onClick={() => { setActive("profile"); setMenuOpen(false); }} className={`art:flex art:min-h-11 art:items-center art:gap-3 art:rounded-xl art:px-3 art:text-sm art:outline-none art:transition-colors art:focus-visible:ring-2 art:focus-visible:ring-ring ${active === "profile" ? "art:bg-muted art:font-medium art:text-foreground" : "art:text-muted-foreground art:hover:bg-muted/50 art:hover:text-foreground"}`}>
                    <svg xmlns="http://www.w3.org/2000/svg" width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-building2 art:lucide-building-2" aria-hidden="true">
                      <path d="M10 12h4"/>
                      <path d="M10 8h4"/>
                      <path d="M14 21v-3a2 2 0 0 0-4 0v3"/>
                      <path d="M6 10H4a2 2 0 0 0-2 2v7a2 2 0 0 0 2 2h16a2 2 0 0 0 2-2V9a2 2 0 0 0-2-2h-2"/>
                      <path d="M6 21V5a2 2 0 0 1 2-2h8a2 2 0 0 1 2 2v16"/>
                    </svg>
                    {"General"}{active === "profile" && (<svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-chevron-right art:ml-auto" aria-hidden="true">
                      <path d="m9 18 6-6-6-6"/>
                    </svg>)}

                  </a>
                  <a href={`#${artemisInstanceId}-R_9bsnpfdb_-features`} aria-current={active === "features" ? "location" : undefined} onClick={() => { setActive("features"); setMenuOpen(false); }} className={`art:flex art:min-h-11 art:items-center art:gap-3 art:rounded-xl art:px-3 art:text-sm art:outline-none art:transition-colors art:focus-visible:ring-2 art:focus-visible:ring-ring ${active === "features" ? "art:bg-muted art:font-medium art:text-foreground" : "art:text-muted-foreground art:hover:bg-muted/50 art:hover:text-foreground"}`}>
                    <svg xmlns="http://www.w3.org/2000/svg" width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-lightbulb" aria-hidden="true">
                      <path d="M15 14c.2-1 .7-1.7 1.5-2.5 1-.9 1.5-2.2 1.5-3.5A6 6 0 0 0 6 8c0 1 .2 2.2 1.5 3.5.7.7 1.3 1.5 1.5 2.5"/>
                      <path d="M9 18h6"/>
                      <path d="M10 22h4"/>
                    </svg>
                    {"AI features"}{active === "features" && (<svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-chevron-right art:ml-auto" aria-hidden="true">
                      <path d="m9 18 6-6-6-6"/>
                    </svg>)}
                  </a>
                </div>
              </div>
              <div>
                <p className="art:mb-2 art:px-3 art:text-xs art:font-medium art:uppercase art:tracking-wide art:text-muted-foreground">
                  {"Publishing"}
                </p>
                <div className="art:space-y-1">
                  <a href={`#${artemisInstanceId}-R_9bsnpfdb_-subdomain`} aria-current={active === "subdomain" ? "location" : undefined} onClick={() => { setActive("subdomain"); setMenuOpen(false); }} className={`art:flex art:min-h-11 art:items-center art:gap-3 art:rounded-xl art:px-3 art:text-sm art:outline-none art:transition-colors art:focus-visible:ring-2 art:focus-visible:ring-ring ${active === "subdomain" ? "art:bg-muted art:font-medium art:text-foreground" : "art:text-muted-foreground art:hover:bg-muted/50 art:hover:text-foreground"}`}>
                    <svg xmlns="http://www.w3.org/2000/svg" width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-earth" aria-hidden="true">
                      <path d="M21.54 15H17a2 2 0 0 0-2 2v4.54"/>
                      <path d="M7 3.34V5a3 3 0 0 0 3 3a2 2 0 0 1 2 2c0 1.1.9 2 2 2a2 2 0 0 0 2-2c0-1.1.9-2 2-2h3.17"/>
                      <path d="M11 21.95V18a2 2 0 0 0-2-2a2 2 0 0 1-2-2v-1a2 2 0 0 0-2-2H2.05"/>
                      <circle cx="12" cy="12" r="10"/>
                    </svg>
                    {"Subdomain"}{active === "subdomain" && (<svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-chevron-right art:ml-auto" aria-hidden="true">
                      <path d="m9 18 6-6-6-6"/>
                    </svg>)}
                  </a>
                  <a href={`#${artemisInstanceId}-R_9bsnpfdb_-domain`} aria-current={active === "domain" ? "location" : undefined} onClick={() => { setActive("domain"); setMenuOpen(false); }} className={`art:flex art:min-h-11 art:items-center art:gap-3 art:rounded-xl art:px-3 art:text-sm art:outline-none art:transition-colors art:focus-visible:ring-2 art:focus-visible:ring-ring ${active === "domain" ? "art:bg-muted art:font-medium art:text-foreground" : "art:text-muted-foreground art:hover:bg-muted/50 art:hover:text-foreground"}`}>
                    <svg xmlns="http://www.w3.org/2000/svg" width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-link2 art:lucide-link-2" aria-hidden="true">
                      <path d="M9 17H7A5 5 0 0 1 7 7h2"/>
                      <path d="M15 7h2a5 5 0 1 1 0 10h-2"/>
                      <line x1="8" x2="16" y1="12" y2="12"/>
                    </svg>
                    {"Custom domain"}{active === "domain" && (<svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-chevron-right art:ml-auto" aria-hidden="true">
                      <path d="m9 18 6-6-6-6"/>
                    </svg>)}
                  </a>
                  <a href={`#${artemisInstanceId}-R_9bsnpfdb_-content`} aria-current={active === "content" ? "location" : undefined} onClick={() => { setActive("content"); setMenuOpen(false); }} className={`art:flex art:min-h-11 art:items-center art:gap-3 art:rounded-xl art:px-3 art:text-sm art:outline-none art:transition-colors art:focus-visible:ring-2 art:focus-visible:ring-ring ${active === "content" ? "art:bg-muted art:font-medium art:text-foreground" : "art:text-muted-foreground art:hover:bg-muted/50 art:hover:text-foreground"}`}>
                    <svg xmlns="http://www.w3.org/2000/svg" width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-file-text" aria-hidden="true">
                      <path d="M6 22a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h8a2.4 2.4 0 0 1 1.704.706l3.588 3.588A2.4 2.4 0 0 1 20 8v12a2 2 0 0 1-2 2z"/>
                      <path d="M14 2v5a1 1 0 0 0 1 1h5"/>
                      <path d="M10 9H8"/>
                      <path d="M16 13H8"/>
                      <path d="M16 17H8"/>
                    </svg>
                    {"Default content"}{active === "content" && (<svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-chevron-right art:ml-auto" aria-hidden="true">
                      <path d="m9 18 6-6-6-6"/>
                    </svg>)}
                  </a>
                </div>
              </div>
            </nav>);
    return (<>
      <div className="art:w-full art:bg-background art:text-foreground">
        <div className="art:mx-auto art:grid art:max-w-7xl art:@min-[768px]/artemis:h-[var(--preview-viewport-height,100svh)] art:@min-[768px]/artemis:grid-cols-[14rem_minmax(0,1fr)] art:@min-[768px]/artemis:overflow-hidden">
          <div className="art:flex art:items-center art:justify-between art:px-5 art:py-3 art:@min-[768px]/artemis:hidden">
            <h2 className="art:text-xl art:font-medium">
              {"Settings"}
            </h2>
            <PressButton type="button" className="art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:text-muted-foreground art:hover:bg-primary/5 art:hover:text-foreground art:focus-visible:outline-none art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:relative art:size-9 art:after:absolute art:after:-inset-1 art:focus-visible:ring-2 art:focus-visible:ring-ring art:h-9 art:rounded-full" onClick={() => setMenuOpen(true)} aria-label="Open settings menu" aria-expanded={menuOpen} aria-haspopup="dialog" tabIndex={0}>
              <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-menu" aria-hidden="true">
                <path d="M4 5h16"/>
                <path d="M4 12h16"/>
                <path d="M4 19h16"/>
              </svg>
            </PressButton>
          </div>
          <aside className="art:hidden art:px-5 art:py-8 art:@min-[768px]/artemis:block">
            <h2 className="art:mb-7 art:px-3 art:text-xl art:font-medium">
              {"Settings"}
            </h2>
            {navigation}
          </aside>
          <form onSubmit={async (event) => {
            event.preventDefault();
            if (!dirty || saving)
                return;
            if (draft.domain && !/^([a-zA-Z0-9-]+\.)+[a-zA-Z]{2,}$/.test(draft.domain)) {
                setError("Enter a domain such as docs.example.com, without a URL path.");
                setEditing("domain");
                return;
            }
            setSaving(true);
            await Promise.resolve();
            setError("");
            setSaved(draft);
            setStatus("Changes saved for this preview.");
            setSaving(false);
        }} className="art:min-h-0 art:min-w-0 art:px-5 art:py-8 art:@min-[640px]/artemis:px-8 art:@min-[768px]/artemis:overflow-y-auto art:@min-[768px]/artemis:overscroll-contain art:@min-[1024px]/artemis:px-12">
            <header className="art:mb-8">
              <h2 className="art:text-xl art:font-medium">
                {"General"}
              </h2>
              <p className="art:mt-2 art:text-sm art:text-muted-foreground">
                {"Manage your organization and how your content is shared."}
              </p>
            </header>
            <fieldset disabled={saving}>
              <section id={`${artemisInstanceId}-R_9bsnpfdb_-profile`} className="art:scroll-mt-6 art:pb-8">
                <h3 className="art:text-xl art:font-medium">
                  {"Organization profile"}
                </h3>
                <div className="art:my-6 art:flex art:items-center art:gap-4">
                  <div className="art:relative art:flex art:size-18 art:shrink-0 art:items-center art:justify-center art:overflow-hidden art:rounded-full art:border art:border-border art:text-xl art:font-medium">
                    {draft.logo ? <img alt={`${draft.name} logo`} className="art:size-full art:object-cover" src={draft.logo}/> : (<svg xmlns="http://www.w3.org/2000/svg" width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-layers" aria-hidden="true">
                      <path d="M12.83 2.18a2 2 0 0 0-1.66 0L2.6 6.08a1 1 0 0 0 0 1.83l8.58 3.91a2 2 0 0 0 1.66 0l8.58-3.9a1 1 0 0 0 0-1.83z"/>
                      <path d="M2 12a1 1 0 0 0 .58.91l8.6 3.91a2 2 0 0 0 1.65 0l8.58-3.9A1 1 0 0 0 22 12"/>
                      <path d="M2 17a1 1 0 0 0 .58.91l8.6 3.91a2 2 0 0 0 1.65 0l8.58-3.9A1 1 0 0 0 22 17"/>
                    </svg>)}
                  </div>
                  <div className="art:min-w-0">
                    <h4 className="art:text-sm art:font-medium">
                      {"Organization logo"}
                    </h4>
                    <p className="art:mt-1 art:text-sm art:text-muted-foreground">
                      {"A square image works best. PNG, JPG, or WebP, up to 2 MB."}
                    </p>
                    <label className="art:relative art:mt-3 art:inline-flex art:h-9 art:cursor-pointer art:items-center art:gap-2 art:rounded-full art:border art:border-border art:px-3 art:text-xs art:font-medium art:transition-colors art:hover:border-muted-foreground/50 art:focus-within:ring-2 art:focus-within:ring-ring">
                      <svg xmlns="http://www.w3.org/2000/svg" width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-upload" aria-hidden="true">
                        <path d="M12 3v12"/>
                        <path d="m17 8-5-5-5 5"/>
                        <path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/>
                      </svg>
                      {"Upload image"}
                      <input onChange={event => { uploadLogo(event.target.files?.[0]); event.currentTarget.value = ""; }} type="file" accept="image/png,image/jpeg,image/webp" aria-label="Upload organization logo" className="art:absolute art:inset-0 art:w-full art:cursor-pointer art:opacity-0"/>
                    </label>
                  </div>
                </div>
                {logoError && <p role="alert" className="art:mb-4 art:text-sm art:text-destructive">{logoError}</p>}
                <div className="art:grid art:max-w-2xl art:gap-6">
                  <div className="art:grid art:items-start art:gap-2 art:@min-[640px]/artemis:grid-cols-[10rem_minmax(0,1fr)] art:@min-[640px]/artemis:gap-6">
                    <label htmlFor={`${artemisInstanceId}-R_9bsnpfdb_-name`} className="art:text-sm art:font-medium art:@min-[640px]/artemis:pt-3">
                      {"Display name"}
                    </label>
                    <div className="art:min-w-0">
                      <div className="art:flex art:flex-col art:gap-1.5 art:w-full art:mt-0">
                        <FieldBox className="art:relative art:h-10 art:overflow-hidden art:rounded-full art:border art:bg-background art:transition-colors art:duration-200 art:border-border">
                          <input id={`${artemisInstanceId}-R_9bsnpfdb_-name`} aria-describedby={`${artemisInstanceId}-R_9bsnpfdb_-name-hint`} required maxLength={80} className="art:peer art:h-full art:w-full art:bg-transparent art:text-sm art:leading-6 art:text-foreground art:caret-foreground art:outline-none art:placeholder:text-muted-foreground/60 art:pl-3.5 art:pr-3.5" value={draft.name} onChange={event => update("name", event.target.value)}/>
                        </FieldBox>
                        <div className="art:contents"/>
                      </div>
                      <p id={`${artemisInstanceId}-R_9bsnpfdb_-name-hint`} className="art:mt-2 art:text-xs art:leading-relaxed art:text-muted-foreground">
                        {"The name your members see in the workspace."}
                      </p>
                    </div>
                  </div>
                  <div className="art:grid art:items-start art:gap-2 art:@min-[640px]/artemis:grid-cols-[10rem_minmax(0,1fr)] art:@min-[640px]/artemis:gap-6">
                    <label htmlFor={`${artemisInstanceId}-R_9bsnpfdb_-organization-id`} className="art:text-sm art:font-medium art:@min-[640px]/artemis:pt-3">
                      {"Organization ID"}
                    </label>
                    <div className="art:min-w-0">
                      <div className="art:flex art:flex-col art:gap-1.5 art:w-full art:min-w-0 art:flex-1">
                        <FieldBox className="art:relative art:h-10 art:overflow-hidden art:rounded-full art:border art:bg-background art:transition-colors art:duration-200 art:border-border">
                          <input id={`${artemisInstanceId}-R_9bsnpfdb_-organization-id`} readOnly className="art:peer art:h-full art:w-full art:bg-transparent art:caret-foreground art:outline-none art:placeholder:text-muted-foreground/60 art:px-3 art:py-2 art:font-mono art:text-xs art:text-muted-foreground" defaultValue="org_workspace_01"/>
                          <span className="art:absolute art:right-0 art:top-0 art:flex art:h-full art:items-center art:text-muted-foreground art:[&_button]:grid art:[&_button]:size-10 art:[&_button]:place-items-center art:[&_svg]:h-4 art:[&_svg]:w-4">
                            <PressButton type="button" className="art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:text-muted-foreground art:hover:bg-primary/5 art:hover:text-foreground art:focus-visible:outline-none art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:size-9 art:shrink-0 art:focus-visible:ring-2 art:focus-visible:ring-inset art:focus-visible:ring-ring art:h-9 art:rounded-full" onClick={copyId} aria-label="Copy organization ID" title="Copy organization ID" tabIndex={0}>
                              <AnimatePresence mode="wait" initial={false}><motion.span key={copy === "copied" ? "copied" : "copy"} initial={{ opacity: 0, scale: reduce ? 1 : 0.85 }} animate={{ opacity: 1, scale: 1 }} exit={{ opacity: 0, scale: reduce ? 1 : 0.85 }} transition={reduce ? { duration: 0 } : { duration: 0.18, ease: ARTEMIS_EASE_OUT }}>{copy === "copied" ? <Check size={16}/> : <Copy size={16}/>}</motion.span></AnimatePresence>
                            </PressButton>
                          </span>
                        </FieldBox>
                        <div className="art:contents"/>
                      </div>
                      <output aria-live="polite" className="art:mt-2 art:block art:min-h-4 art:text-xs art:text-muted-foreground">
                        {copy === "copied" ? "Copied to clipboard." : copy === "error" ? "Couldn\u2019t copy. Select the ID to copy it manually." : "A unique identifier for support and integrations."}
                      </output>
                    </div>
                  </div>
                </div>
              </section>
              <section id={`${artemisInstanceId}-R_9bsnpfdb_-features`} className="art:scroll-mt-6 art:border-t art:border-border art:py-7">
                <h3 className="art:mb-6 art:text-xl art:font-medium">
                  {"AI features"}
                </h3>
                <div className="art:space-y-7">
                  <div className="art:flex art:items-start art:gap-3">
                    <span className="art:flex art:size-10 art:shrink-0 art:items-center art:justify-center art:rounded-full art:border art:border-border">
