                        {"Help your team find answers across your workspace using natural language."}
                      </p>
                    </div>
                    <Toggle id={`${artemisInstanceId}-R_6qapbsnpfdb_`} label="Enable semantic search" checked={draft.semantic} onChange={value => update("semantic", value)}/>
                  </div>
                  <div className="art:flex art:items-start art:gap-3">
                    <span className="art:flex art:size-10 art:shrink-0 art:items-center art:justify-center art:rounded-full art:border art:border-border">
                      <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-lightbulb" aria-hidden="true">
                        <path d="M15 14c.2-1 .7-1.7 1.5-2.5 1-.9 1.5-2.2 1.5-3.5A6 6 0 0 0 6 8c0 1 .2 2.2 1.5 3.5.7.7 1.3 1.5 1.5 2.5"/>
                        <path d="M9 18h6"/>
